QUnit.module("hourSlots.rules",function(hooks){hooks.beforeEach(function(){$("#qunit-fixture").html('<div id="cal"></div>')});hooks.afterEach(function(){try{$("#cal").bsCalendar("destroy")}catch(e){}});QUnit.test("slot color follows availability priority for overlapping rules",function(assert){const done=assert.async(1);$("#cal").bsCalendar({url:null,startView:"day",startDate:"2026-06-15",hourSlots:{start:9,end:12,rules:[{daysOfWeek:[1],startTime:"09:00",endTime:"12:00",mode:"preferred",color:"rgba(40, 120, 60, 0.3)"},{daysOfWeek:[1],startTime:"10:00",endTime:"11:00",mode:"blocked",color:"rgba(220, 53, 69, 0.6)"}]}});setTimeout(function(){const blockedSlot=$("#cal").find('[data-day-hour="10"]');const preferredSlot=$("#cal").find('[data-day-hour="9"]');assert.strictEqual(blockedSlot.css("background-color"),"rgba(220, 53, 69, 0.6)","blocked color wins over earlier preferred color");assert.strictEqual(blockedSlot.attr("data-hour-slot-rules-mode"),"blocked","slot metadata uses the winning rule");assert.strictEqual(preferredSlot.css("background-color"),"rgba(40, 120, 60, 0.3)","non-overlapping preferred slot keeps preferred color");done()},0)})});